  "bugs": {
    "url": "https://github.com/1624318455/opencode-timeline-plugin-v2/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-tui",
    "tui",
    "timeline",
    "sidebar",
    "conversation-history",
    "message-navigation"
